using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using Newtonsoft.Json;
public static class F1FirstLightPrerequisites {
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_1F_Factory.unity"))throw new Exception("Saved 1F edit required");var all=s.GetRootGameObjects();var asset=GraphicsSettings.currentRenderPipeline as UniversalRenderPipelineAsset;if(!asset)throw new Exception("URP required");var so=new SerializedObject(asset);var list=so.FindProperty("m_RendererDataList");var renderers=Enumerable.Range(0,list.arraySize).Select(i=>{var data=list.GetArrayElementAtIndex(i).objectReferenceValue;var rd=new SerializedObject(data);return new{index=i,path=AssetDatabase.GetAssetPath(data),postProcessData=AssetDatabase.GetAssetPath(rd.FindProperty("postProcessData")?.objectReferenceValue)};}).ToArray();
 var result=new{pipeline=AssetDatabase.GetAssetPath(asset),asset.supportsHDR,defaultRenderer=so.FindProperty("m_DefaultRendererIndex").intValue,renderers,cameras=all.SelectMany(g=>g.GetComponentsInChildren<Camera>(true)).Select(c=>{var d=c.GetComponent<UniversalAdditionalCameraData>();return new{path=AnimationUtility.CalculateTransformPath(c.transform,null),c.name,c.enabled,active=c.gameObject.activeInHierarchy,c.tag,c.allowHDR,c.farClipPlane,additionalData=d!=null,post=d&&d.renderPostProcessing,volumeMask=d?d.volumeLayerMask.value:0,renderType=d?d.renderType.ToString():null,rendererIndex=d?new SerializedObject(d).FindProperty("m_RendererIndex").intValue:-99};}).ToArray(),volumes=all.SelectMany(g=>g.GetComponentsInChildren<Volume>(true)).Select(v=>new{path=AnimationUtility.CalculateTransformPath(v.transform,null),v.enabled,active=v.gameObject.activeInHierarchy,v.isGlobal,v.priority,v.weight,layer=v.gameObject.layer,profile=AssetDatabase.GetAssetPath(v.sharedProfile),effects=v.sharedProfile?v.sharedProfile.components.Select(e=>new{type=e.GetType().Name,e.active,parameters=EditorJsonUtility.ToJson(e)}).ToArray():null}).ToArray()};string output=Path.GetFullPath(Application.dataPath+"/../../../Docs/Review/2026-11-13_1F_FirstLight/");Directory.CreateDirectory(output);File.WriteAllText(output+"prerequisites.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
}
